import{_ as t,o,c as a,ae as n}from"./chunks/framework.BvHJbMD4.js";const d=JSON.parse('{"title":"Part 3: The Fate of the Losers","description":"","frontmatter":{},"headers":[],"relativePath":"en/drehbuch/teil-3-das-schicksal-der-verlierer.md","filePath":"en/drehbuch/teil-3-das-schicksal-der-verlierer.md"}'),r={name:"en/drehbuch/teil-3-das-schicksal-der-verlierer.md"};function s(i,e,h,l,c,p){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="part-3-the-fate-of-the-losers" tabindex="-1">Part 3: The Fate of the Losers <a class="header-anchor" href="#part-3-the-fate-of-the-losers" aria-label="Permalink to &quot;Part 3: The Fate of the Losers&quot;">​</a></h1><p><strong>Working Title:</strong> <em>On the Disappearance of Names</em></p><p><strong>Cast:</strong> Oliver Masucci (Alfred Alsberg / Heinz Alsberg), August Diehl (The Young Helmut / A fictional restitution officer), Birgit Minichmayr (Martha Alsberg / The Voice of the Present).</p><hr><h2 id="scene-1-amsterdam-1939-–-waiting-in-the-porcelain-shop" tabindex="-1">Scene 1: Amsterdam 1939 – Waiting in the Porcelain Shop <a class="header-anchor" href="#scene-1-amsterdam-1939-–-waiting-in-the-porcelain-shop" aria-label="Permalink to &quot;Scene 1: Amsterdam 1939 – Waiting in the Porcelain Shop&quot;">​</a></h2><p><strong>Location:</strong> A small, crowded apartment in Amsterdam. Boxes everywhere. <strong>Time:</strong> Shortly before the German occupation of the Netherlands.</p><p>Alfred Alsberg (Oliver Masucci) sits at a shaky table. He tries to create a list of his remaining property. His wife Martha (Birgit Minichmayr) packs silverware in newspaper.</p><p><strong>ALFRED</strong> (bitterly) They&#39;ve named the department store in Duisburg &quot;Horten&quot; now. They didn&#39;t even change the facade. Just the letters above the door. As if you could simply remove a soul with sandpaper.</p><p><strong>MARTHA</strong> We&#39;re safe here, Alfred. Helmut Horten is far away. He has what he wanted. He won&#39;t follow us.</p><p><strong>ALFRED</strong> He&#39;s not following us, Martha. He&#39;s overtaking us. He&#39;s using the wind that drives us away to fill his sails.</p><hr><h2 id="scene-2-the-telephone-dialogue-of-impotence" tabindex="-1">Scene 2: The Telephone Dialogue of Impotence <a class="header-anchor" href="#scene-2-the-telephone-dialogue-of-impotence" aria-label="Permalink to &quot;Scene 2: The Telephone Dialogue of Impotence&quot;">​</a></h2><p><strong>Location:</strong> Split screen. Left: Alfred in Amsterdam. Right: Helmut (August Diehl) in his new luxury office. <strong>Time:</strong> Winter 1939.</p><p><strong>ALFRED</strong> (into the phone) Herr Horten, I demand the final payment. The contract stipulated a sum that we need for our visas.</p><p><strong>HELMUT</strong> (calmly, flipping through files) Herr Dr. Alsberg. I understand your... emotional situation. But the foreign exchange regulations have tightened. The money is in a blocked account. I no longer have access. It&#39;s now... a state matter.</p><p><strong>ALFRED</strong> You blocked the account, Helmut! You gave the state the tip!</p><p><strong>HELMUT</strong> (coldly) I am only optimizing procedures. That is commercial due diligence. I wish you a good journey. Wherever it may lead.</p><p>Helmut hangs up. He wipes the receiver with a white cloth.</p><hr><h2 id="scene-3-the-stolperstein-dialogue-–-meta-level" tabindex="-1">Scene 3: The &quot;Stolperstein Dialogue&quot; – Meta-Level <a class="header-anchor" href="#scene-3-the-stolperstein-dialogue-–-meta-level" aria-label="Permalink to &quot;Scene 3: The &quot;Stolperstein Dialogue&quot; – Meta-Level&quot;">​</a></h2><p><strong>Location:</strong> Bahnhofstraße in Gelsenkirchen in the present day. <strong>Time:</strong> A rainy afternoon.</p><p>We see the Stolpersteine (stumbling stones) for Alfred, Emma, and Martha Alsberg in the ground. Suddenly, the characters step out from the shadows of today&#39;s shops. They are semi-transparent, appearing like projections.</p><p><strong>ALFRED (GHOST)</strong> They walk right over us, Martha. Every day. They&#39;re looking for bargains.</p><p><strong>MARTHA (GHOST)</strong> It&#39;s a good place, Alfred. You can hear the rustling of shopping bags. That&#39;s the sound Helmut loved so much.</p><p><strong>HELMUT (GHOST)</strong> (joins them, elegant as ever) It&#39;s not a bad sound. It&#39;s the sound of the market. The market doesn&#39;t forgive. It simply clears itself. You have become... statistical noise. A small dot in a very large picture.</p><hr><h2 id="scene-4-flight-into-the-unknown" tabindex="-1">Scene 4: Flight into the Unknown <a class="header-anchor" href="#scene-4-flight-into-the-unknown" aria-label="Permalink to &quot;Scene 4: Flight into the Unknown&quot;">​</a></h2><p><strong>Location:</strong> The port of Rotterdam. <strong>Time:</strong> 1940, shortly before the attack.</p><p>Scenes of haste. Alfred tries to get his children Eva, Fritz, and Heinz onto a ship. It is a desperate choreography of separation.</p><p><strong>ALFRED</strong> (to Heinz, played by the young Masucci) Don&#39;t forget the name. But tell no one. A name can be a fortress – or a prison.</p><p><strong>CHRONICLER (Masucci, Off-voice)</strong> While the Alsbergs were negotiating for their naked lives, Helmut Horten was already negotiating for the next expansion. For him, the war was a logistical challenge. For them, it was the end of the world.</p><hr><h2 id="scene-5-the-kafkaesque-restitution-office" tabindex="-1">Scene 5: The Kafkaesque Restitution Office <a class="header-anchor" href="#scene-5-the-kafkaesque-restitution-office" aria-label="Permalink to &quot;Scene 5: The Kafkaesque Restitution Office&quot;">​</a></h2><p><strong>Location:</strong> A grey, dusty office in the post-war era (1952). <strong>Time:</strong> An endless afternoon.</p><p>Heinz Alsberg (Oliver Masucci) sits opposite an officer (August Diehl). The officer wears sleeve protectors and smokes a cigar that smells of cheap state service.</p><p><strong>OFFICER</strong> Mr. Alsberg, we need proof. Where is the original contract from 1936?</p><p><strong>HEINZ</strong> The contract was destroyed in the Duisburg city hall. By Horten&#39;s people. You know that!</p><p><strong>OFFICER</strong> (shrugs) No documents, no expropriation. Perhaps it was a voluntary sale? Mr. Horten is a respected taxpayer. He says it was a fair deal among friends.</p><p><strong>HEINZ</strong> Friends? He let us starve while he drank champagne in our office!</p><hr><h2 id="scene-6-the-ghosts-of-the-department-stores" tabindex="-1">Scene 6: The Ghosts of the Department Stores <a class="header-anchor" href="#scene-6-the-ghosts-of-the-department-stores" aria-label="Permalink to &quot;Scene 6: The Ghosts of the Department Stores&quot;">​</a></h2><p><strong>Location:</strong> In a modern Horten department store at night. <strong>Time:</strong> Present day.</p><p>The camera floats through the perfume department. Suddenly, we hear the whispers of the past. Names of employees dismissed in 1933 echo through the aisles.</p><p><strong>VOICE (Off)</strong> Josephs... Neuss... deported... Alsberg... Cologne... Theresienstadt...</p><p>The cleaning crews work on unmoved. They polish the floor so smooth that you can no longer recognize your own reflection. Only the merchandise.</p><hr><h2 id="scene-7-the-restitution-dance" tabindex="-1">Scene 7: The &quot;Restitution Dance&quot; <a class="header-anchor" href="#scene-7-the-restitution-dance" aria-label="Permalink to &quot;Scene 7: The &quot;Restitution Dance&quot;&quot;">​</a></h2><p><strong>Location:</strong> A courtroom that slowly transforms into a cabaret set. <strong>Time:</strong> 1950s.</p><p>Lawyers in black robes dance around Heinz Alsberg. They throw paragraph slips like confetti.</p><p><strong>LAWYER 1</strong> Statute of limitations! <strong>LAWYER 2</strong> Commercial good faith! <strong>LAWYER 3</strong> Market value adjustment!</p><p>Heinz stands in the middle; he becomes smaller and smaller as the mountains of files grow around him. Helmut Horten (Diehl) sits in the last row and smiles. He offers Heinz a praline.</p><hr><h2 id="scene-8-the-legacy-of-silence" tabindex="-1">Scene 8: The Legacy of Silence <a class="header-anchor" href="#scene-8-the-legacy-of-silence" aria-label="Permalink to &quot;Scene 8: The Legacy of Silence&quot;">​</a></h2><p><strong>Location:</strong> A cemetery in England. <strong>Time:</strong> Much later.</p><p>Eva Alsberg stands at the grave of her parents. She doesn&#39;t speak. She holds an old receipt from the Duisburg department store in her hand. A small piece of paper that still says &quot;Alsberg,&quot; overstamped with a bold &quot;HORTEN.&quot;</p><p><strong>CHRONICLER (Off)</strong> In the end, what remains is not the money. It is the silence. A silence so dearly bought that today it is called discretion. But if you listen closely... between the clicking of heels and the beeping of scanners... you can still hear them. The names that no one wants to pronounce anymore.</p><p><strong>FADE OUT.</strong></p>',57)])])}const u=t(r,[["render",s]]);export{d as __pageData,u as default};
